A = profiles.arm("checked-llc-nolsr"); B = profiles.arm("checked-llc");
ta = A.totals(); tb = B.totals();
sa = A.samples(); sb = B.samples();
indep = {ta, tb, instrDelta: ta.instructions - tb.instructions, pct: 100*(ta.instructions - tb.instructions)/ta.instructions};
({indep, nolsrSamples: sa.slice(0,5), lsrSamples: sb.slice(0,5), nA: sa.length, nB: sb.length})

A = profiles.arm("checked-llc-nolsr"); B = profiles.arm("checked-llc");
sa = A.samples(); sb = B.samples();
({type: typeof sa, keys: Object.keys(sa).slice(0,10), sample: sa})

A = profiles.arm("checked-llc-nolsr"); B = profiles.arm("checked-llc");
ta = A.totals(); tb = B.totals();
sa = A.samples(); sb = B.samples();
rows = Object.keys(sa).map(k => ({row:k, before:sa[k].instructions, after:sb[k].instructions, delta:sa[k].instructions - sb[k].instructions}));
({before:ta.instructions, after:tb.instructions, delta:ta.instructions-tb.instructions, pctOfBefore: 100*(ta.instructions-tb.instructions)/ta.instructions, pctOfAfter: 100*(ta.instructions-tb.instructions)/tb.instructions, ratio: ta.instructions/tb.instructions, rows, sampleKeysA: A.describe().sampleKeys, sampleCountA: A.describe().sampleCount, truncA: A.describe().sampleKeysTruncated})
